import React, { useState, useEffect } from 'react';
import { Activity, ShieldCheck, Zap, Globe } from 'lucide-react';

export default function LivePerformanceMetrics() {
  const [ping, setPing] = useState(8);
  const [msgCount, setMsgCount] = useState(1284592);

  useEffect(() => {
    // Fluctuating latency simulation
    const pingInterval = setInterval(() => {
      setPing(Math.floor(Math.random() * 5) + 7); // 7ms to 11ms
    }, 2000);

    // Live message ticker simulation
    const msgInterval = setInterval(() => {
      setMsgCount((prev) => prev + Math.floor(Math.random() * 3) + 1);
    }, 1200);

    return () => {
      clearInterval(pingInterval);
      clearInterval(msgInterval);
    };
  }, []);

  return (
    <div className="w-full max-w-4xl mx-auto mt-12 p-4 sm:p-6 bg-white/90 backdrop-blur-md rounded-3xl border border-slate-200/80 shadow-xl shadow-sky-950/5">
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4 divide-y md:divide-y-0 md:divide-x divide-slate-100">

        {/* Metric 1: Live Ping */}
        <div className="flex items-center gap-3 p-2">
          <div className="w-10 h-10 rounded-2xl bg-emerald-50 text-emerald-600 flex items-center justify-center shrink-0">
            <Activity className="w-5 h-5 animate-pulse" />
          </div>
          <div>
            <div className="flex items-center gap-1.5">
              <span className="text-lg font-bold text-slate-900 font-mono">{ping} ms</span>
              <span className="w-2 h-2 rounded-full bg-emerald-500 animate-ping"></span>
            </div>
            <p className="text-[11px] font-semibold text-slate-500">Live Latency</p>
          </div>
        </div>

        {/* Metric 2: Live Ticking Messages Counter */}
        <div className="flex items-center gap-3 p-2 pt-4 md:pt-2">
          <div className="w-10 h-10 rounded-2xl bg-sky-50 text-[#006699] flex items-center justify-center shrink-0">
            <Zap className="w-5 h-5" />
          </div>
          <div>
            <div className="text-lg font-bold text-slate-900 font-mono">
              {msgCount.toLocaleString()}
            </div>
            <p className="text-[11px] font-semibold text-slate-500">Live Messages / Sec</p>
          </div>
        </div>

        {/* Metric 3: Encryption */}
        <div className="flex items-center gap-3 p-2 pt-4 md:pt-2">
          <div className="w-10 h-10 rounded-2xl bg-blue-50 text-blue-600 flex items-center justify-center shrink-0">
            <ShieldCheck className="w-5 h-5" />
          </div>
          <div>
            <div className="text-lg font-bold text-slate-900">256-bit AES</div>
            <p className="text-[11px] font-semibold text-slate-500">End-to-End Encrypted</p>
          </div>
        </div>

        {/* Metric 4: Uptime */}
        <div className="flex items-center gap-3 p-2 pt-4 md:pt-2">
          <div className="w-10 h-10 rounded-2xl bg-indigo-50 text-indigo-600 flex items-center justify-center shrink-0">
            <Globe className="w-5 h-5" />
          </div>
          <div>
            <div className="text-lg font-bold text-slate-900">99.99%</div>
            <p className="text-[11px] font-semibold text-slate-500">Global Network Uptime</p>
          </div>
        </div>

      </div>
    </div>
  );
}
